codeExample.code:
// Example of block scope with let and const
function example() {
  if (true) {
    let x = 10;
    const y = 20;
    var z = 30; // var is function-scoped

    console.log(x); // Output: 10
    console.log(y); // Output: 20
    console.log(z); // Output: 30
  }

  // x and y are not accessible here (ReferenceError)
  // console.log(x);
  // console.log(y);

