example();

//Example of const object modification
const myObject = {name: "John", age: 30};
myObject.age = 31; //This is valid. You are modifying the object, not reassigning.
console.log(myObject.age); //Outputs 31

//myObject = {name: "Jane", age: 25}; //This would be invalid because you cannot reassign const

// Arrow function examples

// Simple arrow function with one parameter and implicit return
const square = x => x * x;
console.log(square(5)); // Output: 25

// Arrow function with multiple parameters and explicit return
const add = (a, b) => {
  return a + b;
};
console.log(add(2, 3)); // Output: 5

// Arrow function used as a callback in map
const numbers = [1, 2, 3, 4, 5];
const squaredNumbers = numbers.map(number => number * number);
console.log(squaredNumbers); // Output: [1, 4, 9, 16, 25]

// Lexical 'this' example
const person = {
  name: 'Alice',
  greet: function() {
    setTimeout(() => {
      console.log(`Hello, my name is ${this.name}`); // 'this' refers to person object
    }, 1000);
  }
};

person.greet();

// Template literal examples

const name = 'Alice';
const age = 30;

// String interpolation
const greeting = `Hello, my name is ${name} and I am ${age} years old.`;
console.log(greeting);

// Multi-line string
const poem = `The quick brown fox
 jumps over the lazy dog.
 This is a classic pangram.`;
console.log(poem);

//Expression evaluation
const price = 20;
const quantity = 3;
const total = `Total cost: $${price * quantity}`; //Output Total cost: $60
console.log(total);

// Destructuring examples

// Object destructuring with default values
const config = {
  apiUrl: 'https://api.example.com',
  timeout: 5000
};

const { apiUrl, timeout, maxRetries = 3 } = config; // maxRetries gets default value

console.log(apiUrl);      // Output: https://api.example.com
console.log(timeout);     // Output: 5000
console.log(maxRetries);  // Output: 3

// Array destructuring for swapping variables
